// =========================================
// JQUERY — NO-CONFLICT MODE
// =========================================
//
// Releases jQuery's global $ alias so other
// JavaScript libraries can use it.
//
// The local $ alias remains available inside
// jQuery(function ($) { ... }).
//
// =========================================

if (typeof window.jQuery !== "undefined") {
    window.jQuery.noConflict();
}

/**
 * =========================================
 * PORTFOLIO V2 — NOIR
 * GLOBAL APPLICATION JAVASCRIPT
 * =========================================
 *
 * FEATURES:
 *
 * 1. Automatic copyright year (jQuery)
 * 2. Bidirectional scroll animations (JS)
 * 3. Reduced-motion accessibility (JS)
 * 4. Keyboard navigation detection (jQuery)
 * 5. Email application selection dialog (JS)
 *
 * No additional HTML classes or SCSS required
 * for the original global features.
 *
 * =========================================
 */


// =========================================
// 1. JQUERY — AUTOMATIC COPYRIGHT YEAR
// =========================================
//
// PURPOSE:
// Keep the footer copyright year current.
//
// HOW IT WORKS:
// Read the current year from the system date
// and insert it into the existing footer.
//
// This runs whenever the page is loaded.
//
// =========================================

if (typeof window.jQuery !== "undefined") {

    window.jQuery(function ($) {

        "use strict";

        $("#current-year").text(
            new Date().getFullYear()
        );

    });

}


// =========================================
// 2. NATIVE JAVASCRIPT — SCROLL ANIMATIONS
// =========================================
//
// PURPOSE:
// Animate existing page sections as visitors
// scroll down and back up.
//
// HOW IT WORKS:
//
// - Detect sections automatically.
// - Fade and move sections upward into view.
// - Reset sections after they leave the screen.
// - Repeat animations in both directions.
//
// No HTML or SCSS changes are required.
//
// =========================================

(() => {

    "use strict";

    // =====================================
    // ANIMATION CONFIGURATION
    // =====================================

    const config = {
        selector: "main section",
        distance: 32,
        duration: 650,
        easing: "cubic-bezier(0.22, 1, 0.36, 1)",
        threshold: 0.12
    };

    // =====================================
    // REDUCED MOTION ACCESSIBILITY
    // =====================================
    //
    // Respect the visitor's operating system
    // preference for reduced animation.
    //

    const reducedMotion = window.matchMedia(
        "(prefers-reduced-motion: reduce)"
    );

    // =====================================
    // INITIALIZE SCROLL ANIMATIONS
    // =====================================

    function initScrollAnimations() {

        const sections = document.querySelectorAll(
            config.selector
        );

        if (!sections.length) {
            return;
        }

        if (reducedMotion.matches) {
            return;
        }

        if (!("IntersectionObserver" in window)) {
            return;
        }

        // ---------------------------------
        // PREPARE SECTION ANIMATION STYLES
        // ---------------------------------

        sections.forEach((section) => {

            const bounds = section.getBoundingClientRect();

            const initiallyVisible =
                bounds.top < window.innerHeight &&
                bounds.bottom > 0;

            section.style.transition = [
                `opacity ${config.duration}ms ${config.easing}`,
                `transform ${config.duration}ms ${config.easing}`
            ].join(", ");

            section.style.willChange = "opacity, transform";

            if (initiallyVisible) {

                section.style.opacity = "1";
                section.style.transform =
                    "translateY(0)";

            } else {

                section.style.opacity = "0";
                section.style.transform =
                    `translateY(${config.distance}px)`;

            }

        });

        // ---------------------------------
        // OBSERVE SECTIONS ENTERING VIEW
        // ---------------------------------

        const observer = new IntersectionObserver(
            (entries) => {

                entries.forEach((entry) => {

                    const section = entry.target;

                    if (entry.isIntersecting) {

                        // Reveal section.
                        section.style.opacity = "1";
                        section.style.transform =
                            "translateY(0)";

                    } else {

                        // Reset section for replay.
                        section.style.opacity = "0";
                        section.style.transform =
                            `translateY(${config.distance}px)`;

                    }

                });

            },
            {
                threshold: config.threshold,
                rootMargin: "0px 0px -30px 0px"
            }
        );

        // ---------------------------------
        // START OBSERVING ALL SECTIONS
        // ---------------------------------

        sections.forEach((section) => {
            observer.observe(section);
        });

    }

    // =====================================
    // INITIALIZE AFTER DOM IS READY
    // =====================================

    if (document.readyState === "loading") {

        document.addEventListener(
            "DOMContentLoaded",
            initScrollAnimations
        );

    } else {

        initScrollAnimations();

    }

})();


// =========================================
// 3. JQUERY — KEYBOARD NAVIGATION
// =========================================
//
// PURPOSE:
// Detect whether visitors are navigating
// with a keyboard or pointing device.
//
// HOW IT WORKS:
//
// - Pressing Tab adds .using-keyboard
//   to the HTML element.
//
// - Clicking or tapping removes the class.
//
// This provides a reusable hook for future
// accessibility-focused styling.
//
// =========================================

if (typeof window.jQuery !== "undefined") {

    window.jQuery(function ($) {

        "use strict";

        $(document).on("keydown", function (event) {

            if (event.key === "Tab") {

                $("html").addClass(
                    "using-keyboard"
                );

            }

        });

        $(document).on("pointerdown", function () {

            $("html").removeClass(
                "using-keyboard"
            );

        });

    });

}


// =========================================
// 4. NATIVE JAVASCRIPT — EMAIL DIALOG
// =========================================
//
// PURPOSE:
// Allow visitors to choose their preferred
// email service without relying exclusively
// on the operating system's mailto handler.
//
// FEATURES:
//
// - Opens a native accessible dialog.
// - Supports mobile and desktop buttons.
// - Closes using the close button or Escape.
// - Closes when clicking the backdrop.
// - Copies the email address to clipboard.
// - Restores focus to the opening button.
//
// =========================================

(() => {

    "use strict";

    // =====================================
    // INITIALIZE EMAIL DIALOG
    // =====================================

    function initEmailDialog() {

        const dialog = document.getElementById(
            "contact-email-dialog"
        );

        const openButtons = document.querySelectorAll(
            "[data-email-dialog-open]"
        );

        if (!dialog || !openButtons.length) {
            return;
        }

        const closeButton = dialog.querySelector(
            "[data-email-dialog-close]"
        );

        const copyButton = dialog.querySelector(
            "[data-email-copy]"
        );

        const copyStatus = document.getElementById(
            "email-copy-status"
        );

        let lastFocusedElement = null;

        // ---------------------------------
        // OPEN DIALOG
        // ---------------------------------

        openButtons.forEach((button) => {

            button.addEventListener("click", () => {

                lastFocusedElement = button;

                if (copyStatus) {
                    copyStatus.textContent = "";
                }

                if (!dialog.open) {
                    dialog.showModal();
                }

            });

        });

        // ---------------------------------
        // CLOSE DIALOG
        // ---------------------------------

        if (closeButton) {

            closeButton.addEventListener("click", () => {
                dialog.close();
            });

        }

        // ---------------------------------
        // CLOSE WHEN CLICKING BACKDROP
        // ---------------------------------

        dialog.addEventListener("click", (event) => {

            if (event.target !== dialog) {
                return;
            }

            const bounds = dialog.getBoundingClientRect();

            const clickedInside =
                event.clientX >= bounds.left &&
                event.clientX <= bounds.right &&
                event.clientY >= bounds.top &&
                event.clientY <= bounds.bottom;

            if (!clickedInside) {
                dialog.close();
            }

        });

        // ---------------------------------
        // RESTORE FOCUS AFTER CLOSING
        // ---------------------------------

        dialog.addEventListener("close", () => {

            if (lastFocusedElement) {
                lastFocusedElement.focus();
            }

        });

        // ---------------------------------
        // COPY EMAIL ADDRESS
        // ---------------------------------

        if (copyButton) {

            copyButton.addEventListener(
                "click",
                async () => {

                    const email = copyButton.dataset.emailAddress;

                    if (!email) {
                        return;
                    }

                    try {

                        await navigator.clipboard.writeText(
                            email
                        );

                        if (copyStatus) {
                            copyStatus.textContent =
                                "Email address copied to clipboard.";
                        }

                    } catch (error) {

                        if (copyStatus) {
                            copyStatus.textContent =
                                "Unable to copy automatically. Email: " +
                                email;
                        }

                    }

                }
            );

        }

    }

    // =====================================
    // INITIALIZE AFTER DOM IS READY
    // =====================================

    if (document.readyState === "loading") {

        document.addEventListener(
            "DOMContentLoaded",
            initEmailDialog
        );

    } else {

        initEmailDialog();

    }

})();